css='''
/* v3.0 / StyleKit Neumorphism: a single material and one light source. */
:root{--bg:#e0e5ec;--panel:#e0e5ec;--text:#343e50;--muted:#626d80;--line:#cbd3df;--blue:#506bb7;--gold:#6d5dfc;--green:#16766a;--red:#ad4d64;--shadow:#b8bcc2;--highlight:#fff;--raised:8px 8px 16px #b8bcc2,-8px -8px 16px #fff;--inset:inset 6px 6px 12px #bec5d0,inset -6px -6px 12px #fff;color-scheme:light}
body{background:var(--bg);color:var(--text);font-size:16px;line-height:1.7}.muted,.tiny.muted,.footnote,.scope-note,.code,.mini-label,.range-labels,.legend,footer{color:var(--muted)}
main{max-width:1440px;padding:32px 40px 56px}header{padding-bottom:24px;border:0;gap:24px}.brand{font-size:16px;font-weight:600;letter-spacing:1px}.brand>span:first-child{display:inline-grid;place-items:center;width:44px;height:44px;margin-right:10px;border-radius:14px;background:var(--bg);box-shadow:var(--raised);color:var(--gold)}.brand .muted{color:var(--muted)}.status{color:#33786e;font-size:13px}.hero{padding:40px 0 40px;gap:32px}.eyebrow{color:var(--gold);letter-spacing:2px}h1{font-size:38px;font-weight:600;letter-spacing:-.01em;line-height:1.25}html[lang=en] h1{font-size:36px}.hero .sub{font-size:16px;line-height:1.8;color:#59667a}.hero aside{padding:20px 24px;border-radius:20px;box-shadow:var(--inset);background:var(--bg)}
button,select,input[type=date]{background:var(--bg);color:var(--text);border:0;border-radius:16px;box-shadow:5px 5px 10px #bac1cc,-5px -5px 10px #fff;min-height:46px;padding:12px 18px;font-weight:500;transition:box-shadow .2s ease-out,color .2s ease-out;transform:none}button:hover{background:var(--bg);box-shadow:3px 3px 6px #bac1cc,-3px -3px 6px #fff;color:#5141ce}button:active{box-shadow:var(--inset);transform:none}button.primary{color:var(--gold);background:var(--bg);font-weight:600;box-shadow:var(--raised)}button.primary:hover{box-shadow:4px 4px 8px #b8bcc2,-4px -4px 8px #fff}button.primary:active{box-shadow:var(--inset)}button.active{color:var(--gold);background:var(--bg);border:0;box-shadow:var(--inset)}button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid #6d5dfc;outline-offset:4px}button:disabled{opacity:.5;box-shadow:none}select,input[type=date]{box-shadow:var(--inset);color-scheme:light;padding:12px 16px}.flex{gap:16px}header .flex{gap:16px}.pill{border:0;box-shadow:var(--inset)}
.toolbar{gap:24px;margin:0 0 32px;align-items:center}.segmented{background:var(--bg);box-shadow:var(--inset);border:0;border-radius:20px;padding:8px;gap:8px;justify-self:start}.segmented button{color:var(--muted);box-shadow:none;border-radius:14px;padding:12px 18px}.segmented button.active{color:var(--gold);background:var(--bg);box-shadow:4px 4px 8px #bdc4cf,-4px -4px 8px #fff}.tabs{border:0;gap:16px;margin-bottom:32px}.tabs button{border:0;border-radius:16px;padding:12px 20px;background:var(--bg);box-shadow:4px 4px 8px #bec5d0,-4px -4px 8px #fff;color:var(--muted);font-size:16px}.tabs button.active{box-shadow:var(--inset);color:var(--gold)}
.panel{background:var(--bg);border:0;border-radius:24px;padding:32px;box-shadow:var(--raised);backdrop-filter:none}.cards{gap:32px;margin:32px 0}.grid2{gap:32px}.below{margin-top:32px}.asset-card{overflow:visible}.asset-card:before{display:none}.dot{box-shadow:2px 2px 4px #afb8c7,-2px -2px 4px #fff}.card-title{min-height:36px;gap:12px}.rank{background:var(--bg);box-shadow:var(--inset);border:0;border-radius:9px;padding:5px 9px;font-size:12px}.big{font-size:40px;line-height:1.3;font-weight:600;letter-spacing:-1.5px}.positive{color:var(--green)}.negative{color:var(--red)}.asset-card .card-bottom{border:0;box-shadow:0 -1px 0 #c8d0dc,0 -2px 0 #edf1f6;margin-top:auto;padding-top:18px}.card-money{font-size:24px;color:var(--text)}
.chart-head{margin-bottom:24px;gap:24px}.legend{font-size:14px;gap:12px 24px;align-items:center}.legend>span{line-height:24px}.legend i{box-shadow:1px 1px 2px #aab4c3,-1px -1px 2px #fff}.chart{height:350px}.chart.tall{height:390px}.tip{background:#e0e5ecf7;border:0;border-radius:16px;box-shadow:var(--raised);color:var(--text);padding:14px 18px;font-size:14px}.stat-row{border-bottom:1px solid #c7d0dd;min-height:58px;padding:16px 0}.stat-row strong{font-weight:600}.insight{border:0;border-radius:16px;background:var(--bg);box-shadow:var(--inset);color:#5149a0;padding:18px 20px;margin:24px 0;line-height:1.8}.time-title{font-size:30px;letter-spacing:-.5px;color:#3a4357}.range-labels{color:var(--muted);font-size:14px;line-height:1.7;gap:24px}.timebar{margin-top:24px}
input[type=range]{appearance:none;-webkit-appearance:none;height:12px;border-radius:999px;background:var(--bg);box-shadow:inset 3px 3px 6px #b8c1ce,inset -3px -3px 6px #fff;margin:24px 0 20px;outline-offset:8px;accent-color:#6d5dfc}input[type=range]::-webkit-slider-thumb{appearance:none;-webkit-appearance:none;width:26px;height:26px;background:var(--bg);border:6px solid #6d5dfc;border-radius:50%;box-shadow:4px 4px 8px #aab4c5,-4px -4px 8px #fff;cursor:grab}input[type=range]::-moz-range-thumb{width:16px;height:16px;border:5px solid #6d5dfc;background:var(--bg);border-radius:50%;box-shadow:3px 3px 6px #aab4c5,-3px -3px 6px #fff}input[type=range]:active::-webkit-slider-thumb{cursor:grabbing}
.tablewrap{border-radius:16px;box-shadow:var(--inset);margin-top:24px;padding:8px}table{font-size:15px}td,th{padding:16px 20px;border-bottom:1px solid #c6cfdd;color:var(--text)}th{background:var(--bg);color:#5b677a}td:first-child,th:first-child{background:var(--bg)}tr:last-child td{border-bottom:0}tbody tr:hover td{background:#dce2eb}
.scale{background:linear-gradient(90deg,#c8808f,#e0e5ec,#62b0a2);height:10px;box-shadow:inset 2px 2px 4px #aab4c3,inset -2px -2px 4px #fff}.calendar-grid{gap:10px;margin-top:24px}.cell{border:0;border-radius:10px;color:#344051;box-shadow:3px 3px 6px #b8c1ce,-3px -3px 6px #fff;height:46px;min-height:0;padding:0;transition:box-shadow .2s}.cell:hover{border:0;box-shadow:0 0 0 2px #6d5dfc,3px 3px 6px #b8c1ce;filter:none;color:#293347}.cell.empty{background:var(--bg);box-shadow:var(--inset);opacity:.6}.month,.year{color:#5b677a}.modal-backdrop{background:#64748b66;backdrop-filter:blur(8px)}.modal{background:var(--bg);color:var(--text);border:0;border-radius:24px;padding:32px;box-shadow:var(--raised)}.modal li{color:#485569}.modal a{color:#6250d9}.modal .chart-head{align-items:center}footer{border:0;box-shadow:0 -1px 0 #c6d0de,0 -2px 0 #edf1f6;margin-top:48px;padding-top:24px;color:var(--muted)}
.ambient{background:none}.ambient i{background:var(--bg);filter:none;width:45vw;height:45vw;max-width:720px;max-height:720px;opacity:.2;box-shadow:inset 20px 20px 60px #c3ccd9,inset -20px -20px 60px #fff;left:-25%;top:35%;animation:drift 40s ease-in-out infinite alternate}.ambient i:nth-child(2){background:var(--bg);left:85%;top:-20%;opacity:.3;animation-duration:48s}.ambient i:nth-child(3){display:none}body.motion-off .ambient i{opacity:.12;animation:none}
@media(max-width:1150px){main{padding:24px 32px 48px}.toolbar{gap:20px}.hero{padding:32px 0}.cards{gap:24px}.grid2{gap:24px}.panel{padding:28px}.chart-head:has(>.legend){flex-direction:column}.chart-head>.legend{justify-content:flex-start}.tabs{gap:16px}.below{margin-top:24px}}
@media(max-width:900px){main{padding:24px}.panel{padding:24px}.grid2{grid-template-columns:1fr;gap:24px}.cards{gap:24px}.cell{height:42px;border-radius:8px}.calendar-grid{gap:7px}.hero h1{font-size:32px}.legend{gap:10px 20px}.toolbar{row-gap:20px}header{gap:20px}header .flex{gap:12px}}
@media(max-width:580px){main{padding:20px 16px 32px}.panel{padding:24px 20px}.cards{grid-template-columns:1fr;gap:24px}.hero{padding:32px 0}.hero h1,html[lang=en] h1{font-size:29px}.brand{font-size:15px}.brand>span:first-child{width:36px;height:36px}.brand .tiny{font-size:12px}header .flex{gap:10px}header .flex button{font-size:13px;padding:10px 13px}.status{font-size:12px}.segmented{width:100%;gap:6px;padding:7px;border-radius:18px}.segmented button{padding:10px 9px;font-size:14px}.tabs{gap:10px}.tabs button{font-size:13px;padding:11px 12px}.chart{height:310px}.chart.tall{height:330px}.legend{font-size:13px;gap:10px 16px}.calendar-grid{gap:4px}.cell{height:32px;border-radius:5px;font-size:0}.month,.year{font-size:11px}.tablewrap{margin:20px -4px 0}td,th{padding:14px 16px}.stat-row{gap:18px}.big{font-size:40px}.modal{padding:24px}.toolbar{gap:20px}}
'''
